    @staticmethod
    def decode(s: str) -> 'CountryFlag':
        """Decode CountryFlag from string."""
        parts = s.split('|')
        primary = parts[0]
        name = parts[1]
        year = int(parts[2])
        
        # Convert hex back to RGB tuple (0-1 range)
        rgb = plt.matplotlib.colors.to_rgb(primary)
        
        return CountryFlag(rgb, name=name, year=year)

